-- The tables of a v1 database (release/1.x, last migration 1700000050) that
-- the v1 import reads (#246 part 5), as v1 creates them: columns, types,
-- NOT NULL and defaults, read from a v1 database. Keys, foreign keys and
-- checks are left out: the test fills the tables as v1 would.
CREATE TABLE authors (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  normalized_name text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  status text NOT NULL DEFAULT 'ACTIVE'::text,
  archived_at timestamp with time zone,
  archived_by integer,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by integer
);
CREATE TABLE book_authors (
  book_id integer NOT NULL,
  author_id integer NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0
);
CREATE TABLE book_categories (
  book_id integer NOT NULL,
  category_id integer NOT NULL
);
CREATE TABLE book_formats (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  code text NOT NULL,
  label text NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0
);
CREATE TABLE books (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  isbn text NOT NULL,
  title text NOT NULL,
  genre text,
  publisher text,
  edition text,
  language text,
  format text,
  description text,
  cover_image_url text,
  default_price numeric(14,2),
  trade_value numeric(14,2),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  search_vector tsvector,
  sku text,
  publisher_id integer,
  format_id integer,
  edition_id integer,
  status text NOT NULL DEFAULT 'ACTIVE'::text,
  archived_at timestamp with time zone,
  archived_by integer,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by integer
);
CREATE TABLE branches (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  address text NOT NULL,
  contact_info jsonb NOT NULL,
  operating_hours jsonb NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE categories (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  normalized_name text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  parent_id integer,
  status text NOT NULL DEFAULT 'ACTIVE'::text,
  archived_at timestamp with time zone,
  archived_by integer,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by integer
);
CREATE TABLE customers (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  branch_id integer,
  customer_code text NOT NULL,
  full_name text NOT NULL,
  phone text,
  email text,
  gender text,
  date_of_birth date,
  address text,
  city text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  created_by integer,
  email_encrypted text,
  phone_encrypted text,
  email_lookup text,
  phone_lookup text,
  status text NOT NULL DEFAULT 'ACTIVE'::text,
  archived_at timestamp with time zone,
  archived_by integer,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by integer
);
CREATE TABLE inventory (
  book_id integer NOT NULL,
  location_id integer NOT NULL,
  quantity integer NOT NULL DEFAULT 0,
  reorder_point integer NOT NULL DEFAULT 5,
  version integer NOT NULL DEFAULT 0,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  damaged_quantity integer NOT NULL DEFAULT 0,
  average_cost numeric(14,4) NOT NULL DEFAULT 0,
  inventory_value numeric(14,2) GENERATED ALWAYS AS (round(((quantity)::numeric * average_cost), 2)) STORED
);
CREATE TABLE locations (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  branch_id integer NOT NULL,
  name text NOT NULL,
  is_default_fulfillment boolean NOT NULL DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE loyalty_accounts (
  customer_id integer NOT NULL,
  points_balance numeric(14,2) NOT NULL DEFAULT 0,
  lifetime_points numeric(14,2) NOT NULL DEFAULT 0,
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE pgmigrations (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name character varying(255) NOT NULL,
  run_on timestamp without time zone NOT NULL
);
CREATE TABLE po_line_items (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  po_id bigint NOT NULL,
  book_id integer NOT NULL,
  format_id integer,
  edition_id integer,
  quantity integer NOT NULL,
  unit_cost numeric(14,2) NOT NULL,
  received_quantity integer NOT NULL DEFAULT 0
);
CREATE TABLE publishers (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  status text NOT NULL DEFAULT 'ACTIVE'::text,
  archived_at timestamp with time zone,
  archived_by integer,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by integer
);
CREATE TABLE purchase_orders (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  branch_id integer NOT NULL,
  supplier_id integer NOT NULL,
  status text NOT NULL DEFAULT 'draft'::text,
  total_amount numeric(14,2) NOT NULL DEFAULT 0,
  currency text NOT NULL DEFAULT 'USD'::text,
  expected_delivery_date date,
  notes text,
  created_by integer NOT NULL,
  approved_by integer,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  receiving_branch_id integer,
  receiving_location_id integer,
  financial_status text NOT NULL DEFAULT 'unpaid'::text,
  payment_terms text NOT NULL DEFAULT 'credit'::text
);
CREATE TABLE receivables (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  source_type text NOT NULL,
  source_ref_id text NOT NULL,
  source_entity_id bigint NOT NULL,
  customer_id integer NOT NULL,
  branch_id integer NOT NULL,
  original_amount numeric(14,2) NOT NULL,
  outstanding_amount numeric(14,2) NOT NULL DEFAULT 0,
  currency text NOT NULL DEFAULT 'ETB'::text,
  due_date date,
  settlement_date timestamp with time zone,
  status text NOT NULL DEFAULT 'Pending'::text,
  notes text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE staff (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  username text NOT NULL,
  password_hash text NOT NULL,
  full_name text NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  failed_login_attempts integer NOT NULL DEFAULT 0,
  locked_until timestamp with time zone,
  must_change_password boolean NOT NULL DEFAULT false,
  last_login_at timestamp with time zone,
  password_changed_at timestamp with time zone,
  is_all_branches boolean NOT NULL DEFAULT false
);
CREATE TABLE store_credit_accounts (
  customer_id integer NOT NULL,
  balance numeric(14,2) NOT NULL DEFAULT 0
);
CREATE TABLE supplier_credit_notes (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  po_id bigint NOT NULL,
  supplier_id integer NOT NULL,
  branch_id integer NOT NULL,
  amount numeric(14,2) NOT NULL,
  reason text NOT NULL,
  created_by integer NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE supplier_payments (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  po_id bigint NOT NULL,
  branch_id integer NOT NULL,
  supplier_id integer NOT NULL,
  amount numeric(14,2) NOT NULL,
  payment_method text NOT NULL DEFAULT 'cash'::text,
  source text NOT NULL DEFAULT 'manual'::text,
  notes text,
  created_by integer NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE suppliers (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  contact_info jsonb NOT NULL,
  lead_time_days integer NOT NULL DEFAULT 7,
  pricing_terms text,
  supplier_type text NOT NULL DEFAULT 'external'::text,
  publisher_id integer,
  is_active boolean NOT NULL DEFAULT true,
  is_blacklisted boolean NOT NULL DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  status text NOT NULL DEFAULT 'ACTIVE'::text,
  archived_at timestamp with time zone,
  archived_by integer,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by integer
);
